def build_semantic_pairs(seed=42):
    rng=random.Random(seed);pairs=[]
    for concept,payload in CONCEPTS.items():
        fields=list(payload["fields"]);questions=list(payload["questions"])
        for question in questions:
            shuffled=list(fields);rng.shuffle(shuffled)
            for field in shuffled[:4]:
                pairs.append({"concept":concept,"question":question,"field":field})
    rng.shuffle(pairs);return pairs
